-- Service codes seed (type D + updates + type C)
DELETE FROM service_codes
WHERE created_by = 'SYSTEM';

-- Saudi Arabia entities (RUH, JED, DHA): ECD, DTA, DTC charge types.
INSERT INTO service_codes
(
    id,
    created_by,
    updated_by,
    created_time,
    updated_time,
    entity_code,
    service_code,
    service_description,
    tax_code,
    is_deleted,
    is_active,
    type,
    charge_type,
    fetch_tax,
    doc_type,
    info_axs_id
)
SELECT
    gen_random_uuid(),
    'SYSTEM',
    'SYSTEM',
    NOW(),
    NOW(),
    e.entity_code,
    s.service_code,
    s.service_description,
    s.vat_code,
    CASE WHEN s.service_code = 'absorb' THEN TRUE ELSE FALSE END,
    TRUE,
    'D',
    c.charge_type,
    CASE WHEN s.vat_value > 0 THEN TRUE ELSE FALSE END,
    c.doc_type,
    floor(extract(epoch FROM NOW()))::bigint::text
FROM
    (VALUES
        ('RUH'),
        ('JED'),
        ('DHA')
    ) e(entity_code)
CROSS JOIN
    (VALUES
        ('ECD', 97),
        ('DTA', 96),
        ('DTC', 95)
    ) c(charge_type, doc_type)
CROSS JOIN LATERAL
    (
        SELECT *
        FROM (VALUES
            /* ===== ECD (97) ===== */
            ('Customs Duty Inbound', 'Customs Duty Inbound', 'OOS', 0, 97),
            ('Other Customs Charges', 'Other Customs Charges', 'OOS', 0, 97),
            ('VAT', 'Import VAT', 'OOS', 0, 97),
            ('Transit Charges', 'Transit Charges', 'OOS', 0, 97),
            ('Other Charges', 'Other Charges', 'OOS', 0, 97),
            ('Cost', 'Handling fee', 'OOS', 0, 97),
            ('absorb', 'absorb', 'OOS', 0, 97),

            /* ===== DTA (96) ===== */
            ('Customs Duty Inbound', 'Customs Duty Inbound', 'OOS', 0, 96),
            ('Other Customs Charges', 'Other Customs Charges', 'OOS', 0, 96),
            ('VAT', 'Import VAT', 'OOS', 0, 96),
            ('Transit Charges', 'Transit Charges', 'OOS', 0, 96),
            ('Other Charges', 'Other Charges', 'TAX-15', 15, 96),
            ('Cost', 'Handling fee', 'TAX-15', 15, 96),

            /* ===== DTC (95) ===== */
            ('Customs Duty Inbound', 'Customs Duty Inbound', 'OOS', 0, 95),
            ('Other Customs Charges', 'Other Customs Charges', 'OOS', 0, 95),
            ('VAT', 'Import VAT', 'OOS', 0, 95),
            ('Transit Charges', 'Transit Charges', 'OOS', 0, 95),
            ('Other Charges', 'Other Charges', 'TAX-15', 15, 95),
            ('Cost', 'Handling fee', 'TAX-15', 15, 95)
        ) s(service_code, service_description, vat_code, vat_value, doc_type)
        WHERE s.doc_type = c.doc_type
    ) s;

-- All other entities: DTS, DTT, ECS, ECT charge types.
INSERT INTO service_codes
(
    id,
    created_by,
    updated_by,
    created_time,
    updated_time,
    entity_code,
    service_code,
    service_description,
    tax_code,
    is_deleted,
    is_active,
    type,
    charge_type,
    fetch_tax,
    doc_type,
    info_axs_id
)
SELECT
    gen_random_uuid(),
    'SYSTEM',
    'SYSTEM',
    NOW(),
    NOW(),
    e.code,
    s.service_code,
    s.service_description,
    CASE
        WHEN s.vat_code = 'as per entity tax' THEN 'TAX-'
        ELSE 'OOS'
    END AS tax_code,
    CASE WHEN s.service_code = 'absorb' THEN TRUE ELSE FALSE END,
    TRUE,
    'D',
    c.charge_type,
    CASE
        WHEN s.vat_code = 'as per entity tax' THEN TRUE
        ELSE FALSE
    END AS fetch_tax,
    c.doc_type,
    (floor(extract(epoch FROM clock_timestamp()))::bigint
        + row_number() OVER (ORDER BY e.code, c.doc_type, s.service_code))::text
FROM entity e
CROSS JOIN
(
    VALUES
        ('DTS', 98),
        ('DT3', 99),
        ('ECS', 100),
        ('EC3', 101)
) c(charge_type, doc_type)
CROSS JOIN LATERAL
(
    SELECT *
    FROM
    (
        VALUES
            /* ===== DTS (98) ===== */
            ('Customs Duty Outbound', 'Customs Duty Outbound', 'OOS', 98),
            ('Other Customs Charges', 'Other Customs Charges', 'OOS', 98),
            ('VAT', 'Import VAT', 'OOS', 98),
            ('Transit Charges', 'Transit Charges', 'OOS', 98),
            ('Other Charges', 'Other Charges', 'as per entity tax', 98),
            ('Cost', 'Handling fee', 'as per entity tax', 98),

            /* ===== DTT (99) ===== */
            ('Customs Duty inbound', 'Customs Duty inbound', 'OOS', 99),
            ('Other Customs Charges', 'Other Customs Charges', 'OOS', 99),
            ('VAT', 'Import VAT', 'OOS', 99),
            ('Transit Charges', 'Transit Charges', 'OOS', 99),
            ('Other Charges', 'Other Charges', 'as per entity tax', 99),
            ('Cost', 'Handling fee', 'as per entity tax', 99),

            /* ===== ECS (100) ===== */
            ('Customs Duty Outbound', 'Customs Duty Outbound', 'OOS', 100),
            ('Other Customs Charges', 'Other Customs Charges', 'OOS', 100),
            ('VAT', 'Import VAT', 'OOS', 100),
            ('Transit Charges', 'Transit Charges', 'OOS', 100),
            ('Other Charges', 'Other Charges', 'OOS', 100),
            ('Cost', 'Handling fee', 'OOS', 100),
            ('absorb', 'absorb', 'OOS', 100),

            /* ===== ECT (101) ===== */
            ('Customs Duty inbound', 'Customs Duty inbound', 'OOS', 101),
            ('Other Customs Charges', 'Other Customs Charges', 'OOS', 101),
            ('VAT', 'Import VAT', 'OOS', 101),
            ('Transit Charges', 'Transit Charges', 'OOS', 101),
            ('Other Charges', 'Other Charges', 'OOS', 101),
            ('Cost', 'Handling fee', 'OOS', 101),
            ('absorb', 'absorb', 'OOS', 101)
    ) s
    (
        service_code,
        service_description,
        vat_code,
        doc_type
    )
    WHERE s.doc_type = c.doc_type
) s
WHERE e.code NOT IN ('RUH', 'JED', 'DHA');




